function changeTotalCart(){let total=0;$(".cart-items").find('input[name="total"]').map((indx,item)=>{console.log(),total+=parseFloat($(item).val())}),$(".cart_sub_total").find("span").text(total),$(".cart-total-price").find("strong").text(total)}function changePrice(form,qty,options){let price=qty*options.price;$cartItem=$($(form).parent(".cart-item")),$(form).find('input[name="total"]').val(price),$cartItem.find(".total-price ins").text(price),changeTotalCart()}function GetOptions(form){return{available:$(form).data("instock"),price:$(form).data("price")}}function changeQTY(form,increase){let qty=1,$input=$($(form).find(".qty")),val=0|parseInt($input.val()),options=GetOptions(form);if(increase){let max=void 0!==options.available?options.available:500;qty=val<max?++val:max,$input.val(qty)}else qty=val>1?--val:val,$input.val(qty);changePrice(form,qty,options)}function removeItem(event){$(event).parents(".cart-item").get(0).remove(),changeTotalCart()}$(()=>{$(".cart-item-quantity").on("click",".plus",(function(){$form=$(this).parent(),changeQTY($form,!0)})),$(".cart-item-quantity").on("click",".minus",(function(){$form=$(this).parent(),changeQTY($form,!1)})),$(".remove-item-btn").on("click",(function(){removeItem(this)}))});